// AUTO-GENERATED — do not edit by hand.
// Subset of Roboto (Apache-2.0) covering Basic Latin + Latin-1 + Latin
// Extended-A (Czech háček glyphs) + the symbols used in exports (— · − × Σ …).
// Embedded so jsPDF renders Czech correctly (its built-in Helvetica cannot).
// Regenerate: pyftsubset Roboto-{Regular,Bold}.ttf --unicodes=... then base64.
import type { jsPDF } from 'jspdf';

const ROBOTO_REGULAR = '';
const ROBOTO_BOLD = '';

/**
 * Register the embedded Roboto subset on a jsPDF document and make it active.
 * jsPDF's virtual file system is per-document, so call this once per new jsPDF.
 * Pass font 'Roboto' in jspdf-autotable styles to use it in tables too.
 */
export function registerPdfFont(doc: jsPDF): string {
    doc.addFileToVFS('Roboto-Regular.ttf', ROBOTO_REGULAR);
    doc.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
    doc.addFileToVFS('Roboto-Bold.ttf', ROBOTO_BOLD);
    doc.addFont('Roboto-Bold.ttf', 'Roboto', 'bold');
    doc.setFont('Roboto', 'normal');
    return 'Roboto';
}
